                                                <Globe className="w-5 h-5" />
                                            </div>
                                            <div className="text-left">
                                                <div className={`font-bold text-lg ${language === 'vi' ? 'text-white' : 'text-slate-300'}`}>Tiếng Việt</div>
                                                <div className={`text-xs font-medium ${language === 'vi' ? 'text-indigo-200' : 'text-slate-500'}`}>Vietnamese</div>
                                            </div>
                                        </div>
                                        {language === 'vi' && <Check className="w-6 h-6 text-white" />}
                                    </button>
                                </div>
                            </div>
                        )}

                        {step === 3 && (
                            <div className="space-y-6">
                                <label className="block text-sm font-bold text-slate-300 uppercase tracking-wide">Budget Cycle</label>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <button 
                                        onClick={() => setPeriod('weekly')}
                                        className={`p-6 rounded-2xl border transition-all text-left flex flex-col gap-4 h-full relative overflow-hidden group ${period === 'weekly' ? 'bg-indigo-600 border-indigo-500 shadow-xl' : 'bg-slate-950 border-white/10 hover:border-white/20'}`}
                                    >
                                        <div className="flex justify-between w-full">
                                            <div className={`p-3 rounded-xl ${period === 'weekly' ? 'bg-white/20 text-white' : 'bg-slate-800 text-slate-500'}`}>
                                                <Activity className="w-6 h-6" />
                                            </div>
                                            {period === 'weekly' && <Check className="w-6 h-6 text-white" />}
                                        </div>
                                        <div>
                                            <h4 className={`font-bold text-lg ${period === 'weekly' ? 'text-white' : 'text-slate-200'}`}>Weekly</h4>
                                            <p className={`text-xs mt-1 ${period === 'weekly' ? 'text-indigo-200' : 'text-slate-500'}`}>Every 7 Days</p>
                                        </div>
                                    </button>

                                    <button 
                                        onClick={() => setPeriod('monthly')}
                                        className={`p-6 rounded-2xl border transition-all text-left flex flex-col gap-4 h-full relative overflow-hidden group ${period === 'monthly' ? 'bg-indigo-600 border-indigo-500 shadow-xl' : 'bg-slate-950 border-white/10 hover:border-white/20'}`}
                                    >
                                        <div className="flex justify-between w-full">
                                            <div className={`p-3 rounded-xl ${period === 'monthly' ? 'bg-white/20 text-white' : 'bg-slate-800 text-slate-500'}`}>
                                                <Calendar className="w-6 h-6" />
                                            </div>
                                            {period === 'monthly' && <Check className="w-6 h-6 text-white" />}
                                        </div>
                                        <div>
                                            <h4 className={`font-bold text-lg ${period === 'monthly' ? 'text-white' : 'text-slate-200'}`}>Monthly</h4>
                                            <p className={`text-xs mt-1 ${period === 'monthly' ? 'text-indigo-200' : 'text-slate-500'}`}>Every 30 Days</p>
                                        </div>
                                    </button>
                                </div>
                            </div>
                        )}

                        {step === 4 && (
                            <div className="space-y-6">
                                <label className="block text-sm font-bold text-slate-300 uppercase tracking-wide">Spending Goal</label>
                                <div className="relative group">
                                    <DollarSign className="absolute left-6 top-1/2 -translate-y-1/2 w-6 h-6 text-slate-500 group-focus-within:text-emerald-400 transition-colors" />
                                    <input 
                                        type="number" 
                                        value={limit}
                                        onChange={(e) => setLimit(e.target.value)}
                                        className="w-full bg-slate-950 border border-white/10 rounded-2xl py-5 pl-16 pr-6 text-3xl font-black text-white focus:outline-none focus:border-emerald-500 transition-all placeholder:text-slate-700 shadow-inner"
                                        placeholder="1000"
                                        autoFocus
                                        onKeyDown={(e) => e.key === 'Enter' && handleNext()}
                                    />
                                </div>
                                <div className="flex items-start gap-3 p-4 bg-emerald-500/10 rounded-xl border border-emerald-500/20">
                                    <Wallet className="w-5 h-5 text-emerald-400 shrink-0 mt-0.5" />
                                    <p className="text-xs text-emerald-200 font-medium leading-relaxed">
                                        We'll warn you if you get close to spending this much.
                                    </p>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                <div className="mt-8 pt-8 border-t border-white/5 flex justify-end">
                    <button 
                        onClick={handleNext}
                        disabled={step === 1 && !name.trim()}
                        className="px-8 py-4 bg-white text-slate-950 font-black uppercase text-sm tracking-[0.2em] rounded-xl shadow-[0_0_20px_rgba(255,255,255,0.3)] hover:scale-105 hover:bg-indigo-50 active:scale-95 transition-all flex items-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none group"
                    >
                        {step === totalSteps ? 'Get Started' : 'Continue'} 
                        <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                    </button>
                </div>
            </div>
        </div>
    </div>
  );
};

export default OnboardingModal;

{activeTab === 'insights' && (
    <Insights 
        transactions={transactions}
        goals={goals}
        budgets={budgets}
        userPlan={userPlan}
        onUpgradeClick={() => handleNavigate('plans')}
        formatCurrency={formatCurrency}
        initialPrompt={pendingChatQuery}
        onPromptHandled={() => setPendingChatQuery(null)}
        onApplyBudgets={(newBudgets) => setBudgets(prev => [...prev, ...newBudgets])}
        insightUsage={insightUsage}
        onIncrementUsage={() => handleIncrementUsage('insight')}
        botMode={botMode}
        onNavigate={handleNavigate}
        onAddGoal={(g) => setGoals(prev => [...prev, g])}
        autoScanTriggered={autoScanTrigger}
        activeReport={activeReport}
        spendingLimit={spendingLimit}
        userName={userName}
        creditScore={creditScore}
    />
)}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Send, Lock, Sparkles, RefreshCw, Zap, Crown, Target, Calendar, ChevronRight, Check, Activity, BarChart3, MessageSquare, ArrowUpRight, Lightbulb, Bell, Flame, ShoppingCart, Coffee, Home, Car } from 'lucide-react';
import { BarChart, Bar, Cell, ResponsiveContainer, XAxis, Tooltip } from 'recharts';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
  userName?: string;
  creditScore?: number;
}

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000,
    userName = 'Pilot',
    creditScore = 0
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'I am connected. Auditing financial vectors. State your query or request a report.' 
            : 'Hello! I\'m here to help you optimize your financial wellness. How can I assist you today?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);

  // Dedicated Report State
  const [activeView, setActiveView] = useState<'idle' | 'daily' | 'monthly' | 'ai'>('idle');
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger from external nav
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      }
  }, [activeReport, transactions, spendingLimit]);

  // Initial Prompt Handler
  useEffect(() => {
      if (initialPrompt && onPromptHandled) {
          handleSendMessage(null, initialPrompt);
          onPromptHandled();
      }
  }, [initialPrompt]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setActiveView('daily');
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setActiveView('monthly');
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    setActiveView('ai'); // Switch view immediately to show loading there

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    try {
        const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
        setChatHistory(prev => [...prev, { 
            id: (Date.now() + 1).toString(), 
            role: 'assistant', 
            content: response.message, 
            timestamp: new Date(),
            sentiment: response.sentiment as any,
            suggestedActions: response.suggestedActions
        }]);
    } catch (err) {
        setChatHistory(prev => [...prev, {
            id: (Date.now() + 1).toString(),
            role: 'assistant',
            content: "I'm having trouble connecting to the analysis core right now. Please try again in a moment.",
            timestamp: new Date(),
            sentiment: 'critical'
        }]);
    } finally {
        setChatLoading(false);
    }
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // --- SUB-COMPONENTS ---

  const RiskGauge = ({ score }: { score: number }) => {
      const color = score >= 60 ? '#f43f5e' : score >= 30 ? '#f59e0b' : '#10b981';
      return (
          <div className="relative w-20 h-20 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="40" cy="40" r="32" stroke="#1e293b" strokeWidth="6" fill="transparent" />
                  <circle cx="40" cy="40" r="32" stroke={color} strokeWidth="6" fill="transparent" strokeDasharray={201} strokeDashoffset={201 - (score / 100) * 201} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-xl font-black text-white">{score}</span>
                  <span className="text-[7px] font-bold uppercase tracking-widest text-slate-500">Risk</span>
              </div>
          </div>
      );
  };

  const HealthGauge = ({ score }: { score: number }) => {
      const color = score >= 80 ? '#10b981' : score >= 50 ? '#f59e0b' : '#f43f5e';
      return (
          <div className="relative w-20 h-20 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="40" cy="40" r="32" stroke="#1e293b" strokeWidth="6" fill="transparent" />
                  <circle cx="40" cy="40" r="32" stroke={color} strokeWidth="6" fill="transparent" strokeDasharray={201} strokeDashoffset={201 - (score / 100) * 201} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-xl font-black text-white">{score}</span>
                  <span className="text-[7px] font-bold uppercase tracking-widest text-slate-500">Health</span>
              </div>
          </div>
      );
  };

  const renderDailyReport = () => {
      if (!dailyReport) return null;

      // 1. Data Preparation
      const remainingBudget = Math.max(0, dailyReport.totals.budget * 30 - dailyReport.totals.expense); // Approximation for narrative
      const monthlyBudget = spendingLimit || 1000;
      const monthSpend = transactions
        .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === new Date().getMonth())
        .reduce((sum, t) => sum + t.amount, 0);

      const budgetPercent = Math.min(100, (monthSpend / monthlyBudget) * 100);
      const daysInMonth = new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).getDate();
      const daysRemaining = daysInMonth - new Date().getDate();

      const streak = parseInt(localStorage.getItem('nova_streak') || '0');

      // Top Categories
      const catMap: Record<string, number> = {};
      transactions.filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === new Date().getMonth())
                  .forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
      const topCategories = Object.entries(catMap)
                                  .sort((a,b) => b[1] - a[1])
                                  .slice(0, 3);

      const impactData = [
          { name: 'Mon', value: 40 },
          { name: 'Tue', value: 65 },
          { name: 'Wed', value: 50 },
          { name: 'Thu', value: 90 }, // Highlighted
          { name: 'Fri', value: 60 },
          { name: 'Sat', value: 75 },
          { name: 'Sun', value: 55 },
      ];

      return (
          <div className="animate-slide-up space-y-6 pb-6">

              {/* HERO CARD */}
              <div className="bg-gradient-to-br from-blue-700 to-indigo-900 rounded-[2.5rem] p-8 text-white relative overflow-hidden shadow-2xl">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-[80px] -mr-16 -mt-16"></div>

                  <div className="flex items-center gap-3 mb-6">
                      <span className="bg-white/20 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest backdrop-blur-sm border border-white/10">Daily Narrative</span>
                      <span className="text-blue-200 text-xs font-medium italic">— {new Date(dailyReport.date).toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}</span>
                  </div>

                  <h2 className="text-3xl md:text-4xl font-light leading-tight mb-6">
                      Good morning, <span className="font-bold">{userName}</span>. You're <span className="font-bold text-emerald-300">perfectly on track</span> this month. After yesterday's activity, you've still got <span className="font-bold text-white border-b-2 border-emerald-400">{formatCurrency(Math.max(0, monthlyBudget - monthSpend))}</span> of "guilt-free" spending left before reaching your savings goal.
                  </h2>

                  <div className="flex flex-wrap gap-4">
                      <div className="flex items-center gap-2 bg-emerald-500/20 px-4 py-2 rounded-xl border border-emerald-400/30">
                          <CheckCircle className="w-4 h-4 text-emerald-300" />
                          <span className="text-xs font-bold text-emerald-100">Savings streak active</span>
                      </div>
                      {creditScore > 0 && (
                          <div className="flex items-center gap-2 bg-blue-500/20 px-4 py-2 rounded-xl border border-blue-400/30">
                              <ShieldAlert className="w-4 h-4 text-blue-300" />
                              <span className="text-xs font-bold text-blue-100">Credit score {creditScore}</span>
                          </div>
                      )}
                  </div>
              </div>

              {/* STATS GRID */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {/* Budget Status */}
                  <div className="bg-white text-slate-900 rounded-[2rem] p-6 shadow-xl flex flex-col justify-between h-56">
                      <div className="flex justify-between items-start">
                          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Budget Status</span>
                          <div className="p-2 bg-indigo-50 rounded-xl text-indigo-600"><Target className="w-5 h-5" /></div>
                      </div>
                      <div>
                          <div className="flex items-baseline gap-2 mb-3">
                              <span className="text-3xl font-black tracking-tighter">{formatCurrency(monthSpend)}</span>
                              <span className="text-sm font-bold text-slate-400">of {formatCurrency(monthlyBudget)}</span>
                          </div>
                          <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden mb-4">
                              <div className="h-full bg-indigo-600 rounded-full" style={{ width: `${budgetPercent}%` }}></div>
                          </div>
                          <p className="text-xs text-slate-500 font-medium leading-relaxed">
                              You have used <span className="font-bold text-slate-900">{budgetPercent.toFixed(0)}%</span> of your monthly budget with {daysRemaining} days remaining.
                          </p>
                      </div>
                  </div>

                  {/* Saving Streak */}
                  <div className="bg-white text-slate-900 rounded-[2rem] p-6 shadow-xl flex flex-col justify-between h-56">
                      <div className="flex justify-between items-start">
                          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Saving Streak</span>
                          <div className="p-2 bg-orange-50 rounded-xl text-orange-500"><Flame className="w-5 h-5" /></div>
                      </div>
                      <div className="flex-1 flex flex-col justify-center">
                          <div className="text-6xl font-black text-slate-900 tracking-tighter mb-1">{streak}</div>
                          <p className="text-xs font-bold text-slate-500">Days in a row</p>
                          {streak > 0 && <p className="text-[10px] text-slate-400 mt-1">Personal best: {Math.max(streak, 24)} days</p>}
                      </div>
                      <div className="flex gap-1.5 mt-auto">
                          {[1,2,3,4,5,6].map(i => (
                              <div key={i} className={`h-8 flex-1 rounded-lg ${i > 4 ? 'bg-slate-100' : 'bg-orange-400 opacity-80'}`}></div>
                          ))}
                      </div>
                  </div>

                  {/* Top Categories */}
                  <div className="bg-white text-slate-900 rounded-[2rem] p-6 shadow-xl flex flex-col h-56">
                      <div className="flex justify-between items-center mb-6">
                          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Top Categories</span>
                          <div className="flex gap-1">
                              <div className="w-1 h-1 rounded-full bg-slate-300"></div>
                              <div className="w-1 h-1 rounded-full bg-slate-300"></div>
                              <div className="w-1 h-1 rounded-full bg-slate-300"></div>
                          </div>
                      </div>
                      <div className="space-y-4 flex-1">
                          {topCategories.map(([cat, val], idx) => (
                              <div key={idx} className="flex items-center justify-between">
                                  <div className="flex items-center gap-3">
                                      {cat === Category.FOOD && <Coffee className="w-4 h-4 text-indigo-500" />}
                                      {cat === Category.SHOPPING && <ShoppingCart className="w-4 h-4 text-purple-500" />}
                                      {cat === Category.HOUSING && <Home className="w-4 h-4 text-emerald-500" />}
                                      {cat === Category.TRANSPORT && <Car className="w-4 h-4 text-amber-500" />}
                                      {!['Food & Dining', 'Shopping', 'Housing', 'Transportation'].includes(cat) && <Activity className="w-4 h-4 text-slate-400" />}
                                      <span className="text-sm font-bold text-slate-700 truncate max-w-[100px]">{cat}</span>
                                  </div>
                                  <span className="text-sm font-black text-slate-900">{formatCurrency(val)}</span>
                              </div>
                          ))}
                          {topCategories.length === 0 && <p className="text-xs text-slate-400 italic">No spending data yet.</p>}
                      </div>
                  </div>
              </div>

              {/* BOTTOM SECTION */}
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

                  {/* Coach Deep Dive */}
                  <div className="bg-white text-slate-900 rounded-[2rem] p-8 shadow-xl relative overflow-hidden">
                      <div className="absolute top-0 left-0 w-2 h-full bg-indigo-600"></div>
                      <div className="flex items-center gap-3 mb-6">
                          <div className="bg-indigo-600 p-2 rounded-lg text-white shadow-md">
                              <Bot className="w-5 h-5" />
                          </div>
                          <h3 className="text-lg font-bold text-slate-900">Coach's Deep Dive</h3>
                      </div>

                      <h4 className="text-2xl font-black text-slate-900 mb-4 leading-tight">
                          {dailyReport.action.text || "Review your recent transactions."}
                      </h4>
                      <p className="text-slate-500 mb-8 font-medium leading-relaxed">
                          Based on your current trajectory, you're set to exceed your dining budget by <span className="text-indigo-600 font-bold">$42.00</span>. If you cook at home this Friday and Saturday, you'll hit your <span className="font-bold text-slate-900">"Vacation Fund"</span> milestone two weeks early.
                      </p>

                      <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100 mb-8 flex gap-4">
                          <div className="p-2 bg-indigo-100 rounded-full text-indigo-600 h-fit"><Lightbulb className="w-5 h-5" /></div>
                          <div>
                              <h5 className="text-sm font-bold text-slate-900 mb-1">Actionable Strategy</h5>
                              <p className="text-xs text-slate-500 leading-relaxed">
                                  Meal prep for 20 minutes tonight. It could save you an estimated $35.00 in impulse delivery fees tomorrow evening.
                              </p>
                          </div>
                      </div>

                      <div className="flex flex-wrap gap-4">
                          <button onClick={() => onNavigate('smart_money')} className="px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl text-sm transition-all shadow-lg shadow-indigo-200 flex items-center gap-2">
                              <Zap className="w-4 h-4" /> Set Limit
                          </button>
                          <button className="px-6 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-sm transition-all flex items-center gap-2">
                              <Bell className="w-4 h-4" /> Schedule Reminder
                          </button>
                      </div>
