} from 'lucide-react';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isOnboarded, setIsOnboarded] = useState(false);

  // Core Data
  const [activeTab, setActiveTab] = useState('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
  const [accounts, setAccounts] = useState<Account[]>(ACCOUNTS);
  const [goals, setGoals] = useState<Goal[]>(INITIAL_GOALS);
  const [budgets, setBudgets] = useState<Budget[]>(INITIAL_BUDGETS);

  // User Profile & Settings
  const [userPlan, setUserPlan] = useState<UserPlan>('free');
  const [userName, setUserName] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [userAvatar, setUserAvatar] = useState('');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState('');
  const [currency, setCurrency] = useState<Currency>('USD');
  const [language, setLanguage] = useState<Language>('en');
  const [botMode, setBotMode] = useState<BotMode>('ruthless');
  const [spendingLimit, setSpendingLimit] = useState(1000);
  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>('monthly');
  const [creditScore, setCreditScore] = useState(720);

  // Usage Tracking
  const [insightUsage, setInsightUsage] = useState(0);
  const [negotiationUsage, setNegotiationUsage] = useState(0);

  // UI State
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);
  const [autoScanTrigger, setAutoScanTrigger] = useState(false);
  const [activeReport, setActiveReport] = useState<'daily' | 'monthly' | null>(null);
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Derived State
  const currentSpendingStatus = useMemo(() => {
    // Basic calculation for current period spend
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const spent = transactions
        .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth && new Date(t.date).getFullYear() === currentYear)
        .reduce((sum, t) => sum + t.amount, 0);
    return evaluateSpending(spent, spendingLimit);
  }, [transactions, spendingLimit]);

  const currentPeriodSpend = useMemo(() => {
      const now = new Date();
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();
      return transactions
        .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth && new Date(t.date).getFullYear() === currentYear)
        .reduce((sum, t) => sum + t.amount, 0);
  }, [transactions]);

  // Helpers
  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', {
      style: 'currency',
      currency: currency,
    }).format(amount);
  };

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now().toString();
    setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const handleNavigate = (tab: string, params?: any) => {
    setActiveTab(tab);
    if (params) {
        if (params.query) setPendingChatQuery(params.query);
        if (params.reportType) setActiveReport(params.reportType);
    }
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleIncrementUsage = (type: 'insight' | 'negotiation', amount = 1) => {
      if (type === 'insight') setInsightUsage(prev => prev + amount);
      if (type === 'negotiation') setNegotiationUsage(prev => prev + amount);
  };

  const handleLoginSuccess = (name: string) => {
      setIsLoggedIn(true);
      setUserName(name);
      if (!localStorage.getItem('nova_onboarded')) {
          setIsOnboarded(false);
      } else {
          setIsOnboarded(true);
      }
  };

  const handleOnboardingComplete = (name: string, lang: Language, period: SpendingPeriod, limit: number) => {
      setUserName(name);
      setLanguage(lang);
      setSpendingPeriod(period);
      setSpendingLimit(limit);
      setIsOnboarded(true);
      localStorage.setItem('nova_onboarded', 'true');
      addToast('System Initialized', 'success');
  };

  // Commands for Palette
  const commands: CommandItem[] = [
      { id: 'dash', label: 'Go to Dashboard', group: 'Navigation', icon: <LayoutDashboard className="w-4 h-4" />, action: () => handleNavigate('dashboard') },
      { id: 'tx', label: 'View Transactions', group: 'Navigation', icon: <CreditCard className="w-4 h-4" />, action: () => handleNavigate('transactions') },
      { id: 'ai', label: 'Ask Neural Coach', group: 'Action', icon: <Sparkles className="w-4 h-4" />, action: () => handleNavigate('insights') },
      { id: 'add_tx', label: 'Log New Expense', group: 'Action', icon: <Zap className="w-4 h-4" />, action: () => handleNavigate('transactions') },
      { id: 'settings', label: 'System Settings', group: 'System', icon: <SettingsIcon className="w-4 h-4" />, action: () => handleNavigate('settings') },
  ];

  // Hotkey for Command Palette
  useEffect(() => {
      const down = (e: KeyboardEvent) => {
          if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
              e.preventDefault();
              setIsCommandPaletteOpen((open) => !open);
          }
      };
      document.addEventListener('keydown', down);
      return () => document.removeEventListener('keydown', down);
  }, []);

  if (!isLoggedIn) {
      return <LandingPage onLoginSuccess={handleLoginSuccess} />;
  }

  return (
    <div className={`min-h-screen bg-[#020617] text-slate-200 font-sans selection:bg-indigo-500/30 overflow-hidden flex ${userBackground ? '' : 'bg-gradient-to-br from-[#020617] via-[#0f172a] to-[#020617]'}`}>
        {userBackground && (
            <div className="fixed inset-0 z-0">
                <img src={userBackground} alt="bg" className="w-full h-full object-cover opacity-20" />
                <div className="absolute inset-0 bg-gradient-to-t from-[#020617] via-[#020617]/80 to-transparent"></div>
            </div>
        )}

        {/* Sidebar (Desktop) */}
        <aside className={`fixed top-0 bottom-0 left-0 z-40 w-64 bg-[#0f172a]/90 backdrop-blur-xl border-r border-white/5 transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 md:static`}>
            <div className="h-full flex flex-col p-6">
                <div className="flex items-center gap-3 mb-10">
                    <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-violet-600 flex items-center justify-center shadow-lg shadow-indigo-500/20">
                        <Sparkles className="w-6 h-6 text-white" />
                    </div>
                    <div>
                        <h1 className="text-xl font-bold text-white tracking-tight">Nova</h1>
                        <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest bg-indigo-500/10 px-2 py-0.5 rounded border border-indigo-500/20">Protocol</span>
                    </div>
                </div>

                <nav className="flex-1 space-y-2 overflow-y-auto custom-scrollbar">
                    {NAV_ITEMS.map((item) => {
                        const Icon = item.icon;
                        const isActive = activeTab === item.id;
                        return (
                            <button
                                key={item.id}
                                onClick={() => handleNavigate(item.id)}
                                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 group ${isActive ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-900/20' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}
                            >
                                <Icon className={`w-5 h-5 ${isActive ? 'text-white' : 'text-slate-500 group-hover:text-white'}`} />
                                <span className="text-sm font-bold">{item.label}</span>
                                {isActive && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-white shadow-[0_0_8px_white]"></div>}
                            </button>
                        );
                    })}
                </nav>

                <div className="pt-6 border-t border-white/5 mt-6">
                    <div className="flex items-center gap-3 p-3 rounded-xl bg-slate-900/50 border border-white/5">
                        <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center overflow-hidden border border-white/10">
                            {userAvatar ? (
                                <img src={userAvatar} alt="User" className="w-full h-full object-cover" style={{transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)`}} />
                            ) : (
                                <span className="text-sm font-bold text-slate-400">{userName.charAt(0)}</span>
                            )}
                        </div>
                        <div className="flex-1 min-w-0">
                            <div className="text-sm font-bold text-white truncate">{userName}</div>
                            <div className="text-[10px] text-slate-500 font-medium uppercase tracking-wide truncate">{userPlan} Plan</div>
                        </div>
                        <button onClick={() => setIsLoggedIn(false)} className="p-1.5 text-slate-500 hover:text-rose-400 transition-colors">
                            <LogOut className="w-4 h-4" />
                        </button>
                    </div>
                </div>
            </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 flex flex-col h-screen overflow-hidden relative z-10">
            {/* Mobile Header */}
            <div className="md:hidden flex items-center justify-between p-4 bg-[#0f172a]/90 backdrop-blur-md border-b border-white/5 z-40 sticky top-0">
                <div className="flex items-center gap-2">
                    <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 text-slate-400">
                        {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
                    </button>
                    <span className="font-bold text-white">Nova</span>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => setIsCommandPaletteOpen(true)} className="p-2 text-slate-400">
                        <Search className="w-5 h-5" />
                    </button>
                </div>
            </div>

            {/* Desktop Header / Toolbar */}
            <div className="hidden md:flex items-center justify-between px-8 py-4 bg-transparent sticky top-0 z-30">
                <div className="flex items-center gap-4">
                    <button 
                        onClick={() => setIsCommandPaletteOpen(true)} 
                        className="flex items-center gap-2 px-4 py-2 bg-slate-900/50 border border-white/5 rounded-full text-slate-400 hover:text-white hover:border-white/10 transition-all group"
                    >
                        <Search className="w-4 h-4" />
                        <span className="text-xs font-bold mr-4">Command Core</span>
                        <div className="flex items-center gap-1 text-[10px] font-mono bg-white/5 px-1.5 py-0.5 rounded border border-white/5 text-slate-500 group-hover:text-slate-300">
                            <Command className="w-3 h-3" /> K
                        </div>
                    </button>
                </div>
                <div className="flex items-center gap-4">
                    <button onClick={() => addToast("Notifications aligned.", "info")} className="p-2 text-slate-400 hover:text-white transition-colors relative">
                        <Bell className="w-5 h-5" />
                        <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-rose-500 rounded-full animate-pulse"></span>
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto overflow-x-hidden p-4 md:p-8 custom-scrollbar">
                <div className="max-w-7xl mx-auto h-full">
                    {activeTab === 'dashboard' && (
                        <Dashboard 
                            accounts={accounts}
                            transactions={transactions}
                            goals={goals}
                            budgets={budgets}
                            onNavigate={handleNavigate}
                            onAddTransaction={() => handleNavigate('transactions')}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            onAskCoach={(q) => handleNavigate('insights', { query: q })}
                            spendingStatus={currentSpendingStatus}
                            currentPeriodSpend={currentPeriodSpend}
                            spendingLimit={spendingLimit}
                            spendingPeriod={spendingPeriod}
                            userName={userName}
                            creditScore={creditScore}
                        />
                    )}
                    {activeTab === 'transactions' && (
                        <Transactions 
                            transactions={transactions}
                            accounts={accounts}
                            onAdd={(t) => setTransactions(prev => [t, ...prev])}
                            onDelete={(id) => setTransactions(prev => prev.filter(t => t.id !== id))}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            scanUsage={insightUsage}
                            onIncrementScan={() => handleIncrementUsage('insight')}
                            currency={currency}
                        />
                    )}
                    {activeTab === 'accounts' && (
                        <Accounts 
                            accounts={accounts}
                            budgets={budgets}
                            transactions={transactions}
                            userPlan={userPlan}
                            onAdd={(acc) => setAccounts(prev => [...prev, acc])}
                            onUpdate={(acc) => setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a))}
                            onDelete={(id) => setAccounts(prev => prev.filter(a => a.id !== id))}
                            formatCurrency={formatCurrency}
                            userName={userName}
                            userAvatar={userAvatar}
                            userAvatarZoom={userAvatarZoom}
                            userAvatarPos={userAvatarPos}
                            userBorder={userBorder}
                            onNavigate={handleNavigate}
                        />
                    )}
                    {activeTab === 'insights' && (
                        <Insights 
                            transactions={transactions}
                            goals={goals}
                            budgets={budgets}
                            userPlan={userPlan}
                            onUpgradeClick={() => handleNavigate('plans')}
                            formatCurrency={formatCurrency}
                            initialPrompt={pendingChatQuery}
                            onPromptHandled={() => setPendingChatQuery(null)}
                            onApplyBudgets={(newBudgets) => setBudgets(prev => [...prev, ...newBudgets])}
                            insightUsage={insightUsage}
                            onIncrementUsage={() => handleIncrementUsage('insight')}
                            botMode={botMode}
                            onNavigate={handleNavigate}
                            onAddGoal={(g) => setGoals(prev => [...prev, g])}
                            autoScanTriggered={autoScanTrigger}
                            activeReport={activeReport}
                            spendingLimit={spendingLimit}
                            userName={userName}
                            creditScore={creditScore}
                        />
                    )}
                    {activeTab === 'smart_money' && (
                        <SmartMoney 
                            initialTab={pendingChatQuery === 'BURN_VECTOR' ? 'burn_vector' : undefined} 
                            transactions={transactions}
                            accounts={accounts}
                            goals={goals}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            onUpgradeClick={() => handleNavigate('plans')}
                            insightUsage={insightUsage}
                            onIncrementUsage={(amount) => handleIncrementUsage('insight', amount)}
                            negotiationUsage={negotiationUsage}
                            onIncrementNegotiationUsage={() => handleIncrementUsage('negotiation')}
                        />
                    )}
                    {activeTab === 'goals' && (
                        <Goals 
                            goals={goals}
                            budgets={budgets}
                            transactions={transactions}
                            onAddGoal={(g) => setGoals(prev => [...prev, g])}
                            onUpdateGoal={(g) => setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal))}
                            onAddBudget={(b) => setBudgets(prev => [...prev, b])}
                            onDeleteBudget={(id) => setBudgets(prev => prev.filter(b => b.id !== id))}
                            formatCurrency={formatCurrency}
                        />
                    )}
                    {activeTab === 'plans' && (
                        <Plans 
                            currentPlan={userPlan}
                            onUpgrade={(p) => setUserPlan(p)}
                            onDowngrade={() => setUserPlan('free')}
                            onNavigateDashboard={() => handleNavigate('dashboard')}
                        />
                    )}
                    {activeTab === 'investment' && (
                        <Investment 
                            accounts={accounts}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                        />
                    )}
                    {activeTab === 'upcoming' && <UpcomingFeatures />}
                    {activeTab === 'settings' && (
                        <Settings 
                            userName={userName}
                            userEmail={userEmail}
                            userAvatar={userAvatar}
                            userAvatarZoom={userAvatarZoom}
                            userAvatarPos={userAvatarPos}
                            userBorder={userBorder}
                            userBackground={userBackground}
                            onUpdateBackground={setUserBackground}
                            userPlan={userPlan}
                            onUpdateProfile={(n, e, a, z, p, b) => {
                                setUserName(n); setUserEmail(e); setUserAvatar(a); setUserAvatarZoom(z); setUserAvatarPos(p); setUserBorder(b);
                            }}
                            addToast={addToast}
                            onExportData={() => {
                                const data = { transactions, accounts, goals, budgets, settings: { userName, userPlan, currency, botMode } };
                                const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
                                const url = URL.createObjectURL(blob);
                                const a = document.createElement('a');
                                a.href = url;
                                a.download = `nova_vault_${new Date().toISOString().split('T')[0]}.json`;
                                a.click();
                            }}
                            onImportData={(file) => {
                                const reader = new FileReader();
                                reader.onload = (e) => {
                                    try {
                                        const d = JSON.parse(e.target?.result as string);
                                        if (d.transactions) setTransactions(d.transactions);
                                        if (d.accounts) setAccounts(d.accounts);
                                        if (d.goals) setGoals(d.goals);
                                        if (d.budgets) setBudgets(d.budgets);
                                        addToast('Vault Restored', 'success');
                                    } catch (err) {
                                        addToast('Corrupt Data Capsule', 'error');
                                    }
                                };
                                reader.readAsText(file);
                            }}
                            onClearData={() => {
                                setTransactions([]); setAccounts([]); setGoals([]); setBudgets([]);
                                addToast('System Reset Complete', 'success');
                            }}
                            language={language}
                            onUpdateLanguage={setLanguage}
                            currency={currency}
                            onUpdateCurrency={setCurrency}
                            botMode={botMode}
                            onUpdateBotMode={setBotMode}
                            onDowngrade={() => setUserPlan('free')}
                            spendingLimit={spendingLimit}
                            onUpdateSpendingLimit={setSpendingLimit}
                            spendingPeriod={spendingPeriod}
                            onUpdateSpendingPeriod={setSpendingPeriod}
                            creditScore={creditScore}
                            onUpdateCreditScore={setCreditScore}
                        />
                    )}
                </div>
            </div>

            {/* Overlays */}
            <MobileNav activeTab={activeTab} onNavigate={handleNavigate} onAddTransaction={() => handleNavigate('transactions')} />
            <FloatingAssistant 
                transactions={transactions} 
                budgets={budgets} 
                userPlan={userPlan} 
                botMode={botMode}
                insightUsage={insightUsage}
                onOpenChat={(query) => handleNavigate('insights', { query })} 
                isVisible={activeTab !== 'insights' && activeTab !== 'landing'}
            />
            <CommandPalette 
                isOpen={isCommandPaletteOpen} 
                onClose={() => setIsCommandPaletteOpen(false)} 
                commands={commands} 
            />
            <ToastContainer toasts={toasts} onRemove={removeToast} />

            {!isOnboarded && (
                <OnboardingModal onComplete={handleOnboardingComplete} />
            )}
        </main>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
